CREATE TABLE presets(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL CHECK(length(name)<=64), revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE preset_entries(preset_id TEXT NOT NULL REFERENCES presets(id) ON DELETE CASCADE, zone_id TEXT NOT NULL REFERENCES zones(id), mode TEXT NOT NULL CHECK(mode IN('OFF','STATIC')), brightness REAL NOT NULL CHECK(brightness>=0 AND brightness<=1), PRIMARY KEY(preset_id,zone_id));
CREATE TABLE automation_rules(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), revision INTEGER NOT NULL CHECK(revision>0), schema_version INTEGER NOT NULL CHECK(schema_version=1), dsl TEXT NOT NULL CHECK(length(dsl)<=4096));
CREATE TABLE gesture_mappings(user_id TEXT NOT NULL REFERENCES users(id), gesture TEXT NOT NULL, command_type TEXT NOT NULL, target TEXT NOT NULL, cooldown_ms INTEGER NOT NULL CHECK(cooldown_ms>=0 AND cooldown_ms<=60000), confirmation INTEGER NOT NULL CHECK(confirmation IN(0,1)), PRIMARY KEY(user_id,gesture));
CREATE TABLE button_mappings(device_id TEXT NOT NULL REFERENCES devices(id), press_kind TEXT NOT NULL CHECK(press_kind IN('single','double','long')), owner_id TEXT NOT NULL REFERENCES users(id), command_type TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(device_id,press_kind));
CREATE TABLE automation_audit(id INTEGER PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), rule_ref TEXT NOT NULL, occurred_at INTEGER NOT NULL, result TEXT NOT NULL, reason TEXT NOT NULL);
CREATE INDEX automation_audit_owner_time ON automation_audit(owner_id,occurred_at);
CREATE TABLE habit_learning_state(user_id TEXT PRIMARY KEY REFERENCES users(id), started_at INTEGER NOT NULL, privacy_epoch INTEGER NOT NULL CHECK(privacy_epoch>0), quality TEXT NOT NULL CHECK(quality IN('insufficient','eligible')));
CREATE TABLE habit_observations(id INTEGER PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), occurred_at INTEGER NOT NULL, timezone TEXT NOT NULL, privacy_epoch INTEGER NOT NULL CHECK(privacy_epoch>0), zone_id TEXT NOT NULL REFERENCES zones(id), mode TEXT NOT NULL CHECK(mode IN('OFF','STATIC')), color_rgb INTEGER CHECK(color_rgb>=0 AND color_rgb<=16777215), brightness REAL CHECK(brightness>=0 AND brightness<=1), volume REAL CHECK(volume>=0 AND volume<=1), presence TEXT CHECK(presence IN('PRESENT','PROBABLY_PRESENT','AWAY','UNKNOWN')), ambient_lux REAL CHECK(ambient_lux>=0), monitor_active INTEGER CHECK(monitor_active IN(0,1)), origin TEXT NOT NULL CHECK(origin IN('manual','automation','prediction')), quality TEXT NOT NULL CHECK(quality IN('valid','stale','unknown')));
CREATE INDEX habit_owner_time ON habit_observations(user_id,occurred_at);
CREATE TABLE habit_model_metadata(user_id TEXT NOT NULL REFERENCES users(id), version TEXT NOT NULL, privacy_epoch INTEGER NOT NULL CHECK(privacy_epoch>0), checksum TEXT NOT NULL, trained_at INTEGER NOT NULL, PRIMARY KEY(user_id,version));
CREATE TABLE recommendations(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), privacy_epoch INTEGER NOT NULL CHECK(privacy_epoch>0), model_version TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), command_type TEXT NOT NULL, zone_id TEXT NOT NULL REFERENCES zones(id), mode TEXT NOT NULL CHECK(mode IN('OFF','STATIC')), color_rgb INTEGER CHECK(color_rgb>=0 AND color_rgb<=16777215), brightness REAL CHECK(brightness>=0 AND brightness<=1), volume REAL CHECK(volume>=0 AND volume<=1), created_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','accepted','rejected','expired')), expires_at INTEGER NOT NULL);
CREATE INDEX recommendation_owner_expiry ON recommendations(user_id,status,expires_at);
CREATE TABLE prediction_feedback(recommendation_id TEXT NOT NULL REFERENCES recommendations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), privacy_epoch INTEGER NOT NULL CHECK(privacy_epoch>0), decision TEXT NOT NULL CHECK(decision IN('accepted','rejected')), created_at INTEGER NOT NULL, PRIMARY KEY(user_id,recommendation_id));

CREATE INDEX habit_model_age ON habit_model_metadata(trained_at);
CREATE INDEX recommendation_age ON recommendations(created_at);
CREATE INDEX habit_owner_id ON habit_observations(user_id,id);
